void showNativeExport(HWND parent,HINSTANCE module){auto resource=FindResourceW(module,MAKEINTRESOURCEW(102),RT_RCDATA);auto handle=resource?LoadResource(module,resource):nullptr;auto* data=handle?static_cast<const uint8_t*>(LockResource(handle)):nullptr;DWORD size=resource?SizeofResource(module,resource):0;if(!data||size!=8192){MessageBoxW(parent,L"The embedded native driver resource is unavailable.",L"MM Studio export",MB_OK|MB_ICONERROR);return;}Window dialog(parent,module,Bytes(data,data+size));dialog.run();}
